// Tests for the pure parts of deps-check.mjs. Run: node --test scripts/deps-check.test.mjs

import assert from "node:assert/strict";
import { test } from "node:test";

import {
  addDays,
  ageVerdict,
  diffPackages,
  findAgeException,
  findVulnException,
  osvFindings,
  parseCargoLock,
  parsePnpmLock,
  parsePolicyToml,
  validatePolicy,
} from "./deps-check.mjs";

const CRATES_IO = "registry+https://github.com/rust-lang/crates.io-index";

const cargoLock = (...packages) =>
  [
    "# This file is automatically @generated by Cargo.",
    "version = 4",
    ...packages.map(([name, version, source]) =>
      [
        "",
        "[[package]]",
        `name = "${name}"`,
        `version = "${version}"`,
        source ? `source = "${source}"` : null,
        'checksum = "00"',
        "dependencies = [",
        ' "other",',
        "]",
      ]
        .filter((l) => l !== null)
        .join("\n"),
    ),
  ].join("\n");

test("parseCargoLock reads name, version, and source, with none for workspace crates", () => {
  const text = cargoLock(["serde", "1.0.228", CRATES_IO], ["ersa-core", "0.1.0"]);
  assert.deepEqual(parseCargoLock(text), [
    { name: "serde", version: "1.0.228", source: CRATES_IO },
    { name: "ersa-core", version: "0.1.0", source: null },
  ]);
});

test("parseCargoLock handles CRLF line endings and an empty file", () => {
  assert.deepEqual(parseCargoLock(cargoLock(["a", "1.0.0", CRATES_IO]).replace(/\n/g, "\r\n")), [
    { name: "a", version: "1.0.0", source: CRATES_IO },
  ]);
  assert.deepEqual(parseCargoLock(""), []);
});

test("diffPackages returns added crates and changed versions, not unchanged ones", () => {
  const base = parseCargoLock(cargoLock(["serde", "1.0.227", CRATES_IO], ["tokio", "1.48.0", CRATES_IO]));
  const head = parseCargoLock(
    cargoLock(["serde", "1.0.228", CRATES_IO], ["tokio", "1.48.0", CRATES_IO], ["rusqlite", "0.37.0", CRATES_IO]),
  );
  assert.deepEqual(
    diffPackages(base, head).map((p) => `${p.name}@${p.version}`),
    ["serde@1.0.228", "rusqlite@0.37.0"],
  );
});

test("diffPackages keeps a second version of a crate the base already has, and treats a missing base as empty", () => {
  const base = parseCargoLock(cargoLock(["syn", "1.0.109", CRATES_IO]));
  const head = parseCargoLock(cargoLock(["syn", "1.0.109", CRATES_IO], ["syn", "2.0.100", CRATES_IO]));
  assert.deepEqual(diffPackages(base, head).map((p) => p.version), ["2.0.100"]);
  assert.equal(diffPackages(parseCargoLock(""), head).length, 2);
});

const PNPM_V9 = `lockfileVersion: '9.0'

settings:
  autoInstallPeers: true

importers:

  .:
    dependencies:
      react-dom:
        specifier: ^18.2.0
        version: 18.2.0(react@18.2.0)

packages:

  '@types/node@22.1.0':
    resolution: {integrity: sha512-x}

  lodash@4.17.21:
    resolution: {integrity: sha512-y}

  react-dom@18.2.0:
    resolution: {integrity: sha512-z}
    peerDependencies:
      react: ^18.2.0

  local-thing@file:../local-thing:
    resolution: {directory: ../local-thing, type: directory}

  typescript@5.6.0-beta:
    resolution: {integrity: sha512-w}

snapshots:

  lodash@4.17.21: {}

  react-dom@18.2.0(react@18.2.0):
    dependencies:
      react: 18.2.0
`;

test("parsePnpmLock reads the packages map of a v9 lockfile, including scoped names", () => {
  assert.deepEqual(parsePnpmLock(PNPM_V9), [
    { name: "@types/node", version: "22.1.0", source: "npm" },
    { name: "lodash", version: "4.17.21", source: "npm" },
    { name: "react-dom", version: "18.2.0", source: "npm" },
    { name: "local-thing", version: "file:../local-thing", source: "file:../local-thing" },
    { name: "typescript", version: "5.6.0-beta", source: "npm" },
  ]);
});

test("parsePnpmLock reads v6 keys with a leading slash and peer suffixes", () => {
  const v6 = `lockfileVersion: '6.0'

packages:

  /react-dom@18.2.0(react@18.2.0):
    resolution: {integrity: sha512-z}
    dev: false

  /@scope/pkg@1.2.3:
    resolution: {integrity: sha512-a}
`;
  assert.deepEqual(parsePnpmLock(v6), [
    { name: "react-dom", version: "18.2.0", source: "npm" },
    { name: "@scope/pkg", version: "1.2.3", source: "npm" },
  ]);
});

test("diffPackages works on pnpm lockfiles", () => {
  const head = PNPM_V9.replace("lodash@4.17.21:\n    resolution", "lodash@4.17.22:\n    resolution");
  assert.deepEqual(
    diffPackages(parsePnpmLock(PNPM_V9), parsePnpmLock(head)).map((p) => `${p.name}@${p.version}`),
    ["lodash@4.17.22"],
  );
});

const TODAY = "2026-11-01";

const policy = (text) => validatePolicy(parsePolicyToml(text), TODAY);

test("the committed deps-policy.toml is valid", async () => {
  const { readFileSync } = await import("node:fs");
  const text = readFileSync(new URL("../deps-policy.toml", import.meta.url), "utf8");
  const p = policy(text);
  assert.deepEqual(p.problems, []);
  assert.equal(p.minAgeDays, 7);
});

test("parsePolicyToml reads strings, integers, bare dates, comments, and arrays of tables", () => {
  const doc = parsePolicyToml(`min_age_days = 7 # a week
[[age_exception]]
ecosystem = "crates.io"
package = "a"
version = "1.0.0"
reason = "Fixes \\"bug\\" #12"
expires = 2026-12-01
`);
  assert.deepEqual(doc, {
    min_age_days: 7,
    age_exception: [
      { ecosystem: "crates.io", package: "a", version: "1.0.0", reason: 'Fixes "bug" #12', expires: { date: "2026-12-01" } },
    ],
  });
});

test("parsePolicyToml rejects syntax it does not read, naming the line", () => {
  assert.throws(() => parsePolicyToml("min_age_days = [7]"), /line 1: unsupported value/);
  assert.throws(() => parsePolicyToml("\n\nnot toml"), /line 3: cannot read/);
  assert.throws(() => parsePolicyToml("a = 1\na = 2"), /line 2: "a" is set twice/);
});

test("validatePolicy accepts unexpired exceptions with a reason, up to 90 days out", () => {
  const p = policy(`min_age_days = 7
[[age_exception]]
ecosystem = "npm"
package = "@scope/x"
version = "2.0.0"
reason = "Fixes a vulnerability."
expires = ${addDays(TODAY, 90)}
[[vulnerability_exception]]
id = "RUSTSEC-2024-0001"
reason = "No fix yet."
expires = ${TODAY}
`);
  assert.deepEqual(p.problems, []);
  assert.equal(p.ageExceptions[0].expires, "2027-01-30");
  assert.equal(p.vulnExceptions[0].id, "RUSTSEC-2024-0001");
});

test("validatePolicy fails an expired exception and says what to do", () => {
  const p = policy(`min_age_days = 7
[[vulnerability_exception]]
id = "GHSA-43w2-9j62-hq99"
reason = "No fix yet."
expires = 2026-10-31
`);
  assert.equal(p.problems.length, 1);
  assert.match(p.problems[0], /expired on 2026-10-31; remove it .* or renew it/);
});

test("validatePolicy fails an exception missing its reason or expiry, or expiring too far out", () => {
  const p = policy(`min_age_days = 7
[[age_exception]]
ecosystem = "crates.io"
package = "a"
version = "1.0.0"
[[age_exception]]
ecosystem = "crates.io"
package = "b"
version = "1.0.0"
reason = "   "
expires = ${addDays(TODAY, 91)}
`);
  assert.equal(p.problems.length, 4);
  assert.match(p.problems[0], /#1 \(a@1\.0\.0\): add a reason/);
  assert.match(p.problems[1], /#1 \(a@1\.0\.0\): add expires = YYYY-MM-DD/);
  assert.match(p.problems[2], /#2 \(b@1\.0\.0\): add a reason/);
  assert.match(p.problems[3], /#2 \(b@1\.0\.0\): expires 2027-01-31 is more than 90 days out; use 2027-01-30/);
});

test("validatePolicy rejects unknown fields, bad ecosystems and IDs, and a missing threshold", () => {
  const p = policy(`[[age_exception]]
ecosystem = "pypi"
package = "a"
version = "1"
reason = "r"
expires = ${TODAY}
note = "typo"
[[vulnerability_exception]]
id = "CVE-21"
reason = "r"
expires = ${TODAY}
`);
  assert.deepEqual(
    p.problems.map((m) => m.replace(/^.*?: /, "")),
    [
      "set min_age_days to a whole number of days",
      'age_exception #1 (a@1): set ecosystem to "crates.io" or "npm"',
      'age_exception #1 (a@1): unknown field "note" (fields are ecosystem, package, version, reason, expires)',
      "vulnerability_exception #1 (CVE-21): set id to a RUSTSEC-, GHSA-, or CVE- advisory ID",
    ],
  );
});

test("findAgeException matches ecosystem, package, and exact version", () => {
  const exceptions = [{ ecosystem: "crates.io", package: "a", version: "1.0.1", reason: "r", expires: TODAY }];
  assert.equal(findAgeException(exceptions, "crates.io", "a", "1.0.1"), exceptions[0]);
  assert.equal(findAgeException(exceptions, "crates.io", "a", "1.0.2"), null);
  assert.equal(findAgeException(exceptions, "npm", "a", "1.0.1"), null);
});

test("ageVerdict fails a version younger than the threshold and allows it with an exception", () => {
  const now = new Date("2026-11-01T12:00:00Z");
  const sixDaysOld = new Date("2026-10-26T12:00:01Z");
  const sevenDaysOld = new Date("2026-10-25T12:00:00Z");
  const bare = { minAgeDays: 7, ageExceptions: [] };
  const excepted = {
    minAgeDays: 7,
    ageExceptions: [{ ecosystem: "crates.io", package: "a", version: "1.0.1", reason: "Fixes a vulnerability.", expires: TODAY }],
  };
  assert.equal(ageVerdict(bare, "crates.io", "a", "1.0.1", sevenDaysOld, now).status, "ok");
  assert.equal(ageVerdict(bare, "crates.io", "a", "1.0.1", sixDaysOld, now).status, "fail");
  const allowed = ageVerdict(excepted, "crates.io", "a", "1.0.1", sixDaysOld, now);
  assert.equal(allowed.status, "allow");
  assert.equal(allowed.exception, excepted.ageExceptions[0]);
  assert.equal(ageVerdict(excepted, "npm", "a", "1.0.1", sixDaysOld, now).status, "fail");
});

// The shape OSV-Scanner 2.x prints with --format json.
const OSV_REPORT = {
  results: [
    {
      source: { path: "Cargo.lock", type: "lockfile" },
      packages: [
        {
          package: { name: "smallvec", version: "1.6.0", ecosystem: "crates.io" },
          vulnerabilities: [
            { id: "RUSTSEC-2021-0003", aliases: ["CVE-2021-25900", "GHSA-43w2-9j62-hq99"] },
            { id: "GHSA-43w2-9j62-hq99", aliases: ["CVE-2021-25900", "RUSTSEC-2021-0003"] },
          ],
          groups: [
            {
              ids: ["RUSTSEC-2021-0003", "GHSA-43w2-9j62-hq99"],
              aliases: ["CVE-2021-25900", "GHSA-43w2-9j62-hq99", "RUSTSEC-2021-0003"],
              max_severity: "9.8",
            },
          ],
        },
      ],
    },
  ],
};

test("osvFindings reports one finding per advisory group with every ID and alias", () => {
  assert.deepEqual(osvFindings(OSV_REPORT), [
    {
      ecosystem: "crates.io",
      name: "smallvec",
      version: "1.6.0",
      ids: ["RUSTSEC-2021-0003", "GHSA-43w2-9j62-hq99", "CVE-2021-25900"],
      severity: "9.8",
      lockfile: "Cargo.lock",
    },
  ]);
  assert.deepEqual(osvFindings({ results: [] }), []);
});

test("findVulnException matches an advisory by its ID or any alias", () => {
  const [finding] = osvFindings(OSV_REPORT);
  for (const id of ["RUSTSEC-2021-0003", "GHSA-43w2-9j62-hq99", "CVE-2021-25900"]) {
    const exceptions = [{ id, reason: "r", expires: TODAY }];
    assert.equal(findVulnException(exceptions, finding.ids), exceptions[0], id);
  }
  assert.equal(findVulnException([{ id: "RUSTSEC-2020-0071", reason: "r", expires: TODAY }], finding.ids), null);
});
